package com.vibecode.output.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="output_analysis_records") public class OutputAnalysisRecord { @Id private UUID id; @Column(name="evidence_id",nullable=false,unique=true) private UUID evidenceId; @Enumerated(EnumType.STRING) @Column(nullable=false) private OutputAnalysisStatus status; @Column(nullable=false,columnDefinition="TEXT") private String summary; @Column(nullable=false,columnDefinition="TEXT") private String signals; @Column(name="should_continue",nullable=false) private boolean shouldContinue; @Column(name="requires_correction",nullable=false) private boolean requiresCorrection; @Column(name="created_at",nullable=false) private Instant createdAt; protected OutputAnalysisRecord(){} public OutputAnalysisRecord(UUID evidenceId,OutputAnalysis a){id=UUID.randomUUID();this.evidenceId=evidenceId;status=a.status();summary=a.summary();signals=a.signals().stream().map(Enum::name).reduce((x,y)->x+","+y).orElse("");shouldContinue=a.shouldContinue();requiresCorrection=a.requiresCorrection();createdAt=Instant.now();} public OutputAnalysisStatus status(){return status;} public String summary(){return summary;} public List<String> signals(){return signals.isBlank()?List.of():List.of(signals.split(","));} public boolean shouldContinue(){return shouldContinue;} public boolean requiresCorrection(){return requiresCorrection;} public Instant createdAt(){return createdAt;} }
